-- Policy B staging kit, step S06. Generated by scripts/db-verify/staging/build-policy-b-kit.sh
-- from the policy B cases. Do not edit; rebuild. Staging only: never run against the production project.

-- Refuse to run anywhere but an empty or synthetic-only staging database.
DO $guard$
DECLARE
  v_bad boolean;
BEGIN
  IF to_regclass('public.vehicle_listings') IS NOT NULL THEN
    EXECUTE $q$SELECT EXISTS (SELECT 1 FROM public.vehicle_listings WHERE vin NOT LIKE 'EXAMPLEVIN%')$q$ INTO v_bad;
    IF v_bad THEN RAISE EXCEPTION 'staging guard: non-synthetic vehicles present; this is not the policy B staging database'; END IF;
  END IF;
  IF to_regclass('public.tenants') IS NOT NULL THEN
    EXECUTE $q$SELECT EXISTS (SELECT 1 FROM public.tenants WHERE slug NOT LIKE '%example-motors')$q$ INTO v_bad;
    IF v_bad THEN RAISE EXCEPTION 'staging guard: non-synthetic dealerships present; this is not the policy B staging database'; END IF;
  END IF;
END
$guard$;

UPDATE t.config SET stage = 'policy B';
-- ===== scripts/db-verify/30_fee_basis.sql =====
-- Policy B (supabase/proposed/20261031000000_doc_fee_basis_policy_b.sql).
-- Third (b..03): fee-inclusive, no conflicts. Fourth (b..04): fee-inclusive
-- with one of each conflict. Example Motors (b..01): set to fee-exclusive
-- inside the cases that need it. Every case is rolled back.

CREATE FUNCTION t.ver(p_tenant uuid) RETURNS bigint LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS
$$ SELECT policy_version FROM public.dealer_profiles WHERE tenant_id = p_tenant $$;
CREATE FUNCTION t.vrow(p_id uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS
$$ SELECT concat_ws('|', price, advertised_price_before_doc, doc_fee, website_sale_price) FROM public.vehicle_listings WHERE id = p_id $$;
CREATE FUNCTION t.tenant_hash(p_tenant uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS
$$ SELECT md5(string_agg(v::text, ',' ORDER BY id)) FROM public.vehicle_listings v WHERE tenant_id = p_tenant $$;
GRANT EXECUTE ON FUNCTION t.ver(uuid), t.vrow(uuid), t.tenant_hash(uuid) TO authenticated;
CREATE TABLE t.hash AS SELECT 'b0000000-0000-4000-8000-000000000003'::uuid AS tenant_id, t.tenant_hash('b0000000-0000-4000-8000-000000000003') AS h
  UNION ALL SELECT 'b0000000-0000-4000-8000-000000000004', t.tenant_hash('b0000000-0000-4000-8000-000000000004');
GRANT SELECT ON t.hash TO authenticated;

-- ── Basis authority: only the explicit setting decides ───────────────────
SELECT t.expect('fee basis', 'basis rule (inc true | inc "false" | legacy exc false | display mode alone | nothing | contradiction | unreadable | both agree | null)', 'owner',
  $q$SELECT string_agg(b.basis || ':' || b.basis_source, ' ' ORDER BY n) FROM (VALUES
       (1, '{"advertised_includes_doc_fee": true}'::jsonb),
       (2, '{"advertised_includes_doc_fee": "false", "price_display_mode": "website_sale_price"}'),
       (3, '{"advertised_excludes_doc_fee": false}'),
       (4, '{"price_display_mode": "website_sale_price"}'),
       (5, '{}'),
       (6, '{"advertised_includes_doc_fee": true, "advertised_excludes_doc_fee": true}'),
       (7, '{"advertised_includes_doc_fee": "yes"}'),
       (8, '{"advertised_includes_doc_fee": true, "advertised_excludes_doc_fee": false}'),
       (9, '{"advertised_includes_doc_fee": null}')) v(n, s),
     LATERAL public.doc_fee_basis(v.s) b$q$,
  'includes_fee:advertised_includes_doc_fee before_fee:advertised_includes_doc_fee includes_fee:advertised_excludes_doc_fee unconfigured:not_set unconfigured:not_set conflict:settings_conflict unconfigured:unreadable_setting includes_fee:advertised_includes_doc_fee unconfigured:not_set');

-- ── Fee-inclusive, no conflicts: the traced vehicle, $895 -> $925 ─────────
SELECT t.expect('fee basis: includes fee', 'dry-run (basis|eligible|unchanged|archived excluded|no price|split|invalid|sale price differs|evidence|blocked)', 'fee_owner',
  $q$SELECT concat_ws('|', r->>'basis', r->>'eligible', r->>'unchanged', r->>'excluded_archived', r->>'no_price_basis', r->>'split_mismatches', r->>'invalid', r->>'source_mismatches', r->>'evidence_conflicts', r->>'blocked')
     FROM public.admin_doc_fee_change_preview('b0000000-0000-4000-8000-000000000003', true, 925) r$q$,
  'includes_fee|2|0|1|1|0|0|0|0|false');
SELECT t.expect('fee basis: includes fee', 'dry-run sample for the traced vehicle keeps the total and moves the split (selling before>after|fee|total before>after)', 'fee_owner',
  $q$SELECT (s->>'selling_before')::numeric || '>' || (s->>'selling_after')::numeric || '|' || (s->>'fee_before')::numeric || '>' || (s->>'fee_after')::numeric || '|' || (s->>'total_before')::numeric || '>' || (s->>'total_after')::numeric
     FROM public.admin_doc_fee_change_preview('b0000000-0000-4000-8000-000000000003', true, 925) r, jsonb_array_elements(r->'samples') s
     WHERE s->>'vin_suffix' = '040420'$q$,
  '39525.00>39495.00|895>925.00|40420.00>40420.00');
SELECT t.check('fee basis: includes fee', 'the dry-run writes nothing (rows|version|audit rows)', 'fee_owner',
  $q$SELECT public.admin_doc_fee_change_preview('b0000000-0000-4000-8000-000000000003', true, 925)$q$, 'ok rows=1',
  $q$SELECT concat_ws('|', t.tenant_hash('b0000000-0000-4000-8000-000000000003') = (SELECT h FROM t.hash WHERE tenant_id = 'b0000000-0000-4000-8000-000000000003'), t.ver('b0000000-0000-4000-8000-000000000003'), (SELECT count(*) FROM public.audit_log))$q$,
  't|1|0');
SELECT t.check('fee basis: includes fee', 'apply keeps the advertised total: traced row (price|before-fee|fee|website_sale_price)', 'fee_owner',
  $q$SELECT public.admin_doc_fee_change_apply('b0000000-0000-4000-8000-000000000003', true, 925, 1, 'policy-b-0001')$q$, 'ok',
  $q$SELECT t.vrow('c0000000-0000-4000-8000-000000000301')$q$,
  '40420.00|39495.00|925.00|40420');
SELECT t.check('fee basis: includes fee', 'apply result (status|affected|basis)', 'fee_owner',
  $q$CREATE TEMP TABLE r ON COMMIT DROP AS SELECT public.admin_doc_fee_change_apply('b0000000-0000-4000-8000-000000000003', true, 925, 1, 'policy-b-0002') AS j$q$, 'ok',
  $q$SELECT concat_ws('|', j->>'status', j->>'affected', j->>'basis') FROM r$q$,
  'applied|2|includes_fee');
SELECT t.check('fee basis: includes fee', 'after reload: Label (price) = Passport total and Passport selling = price - fee = stored before-fee, every changed row', 'fee_owner',
  $q$SELECT public.admin_doc_fee_change_apply('b0000000-0000-4000-8000-000000000003', true, 925, 1, 'policy-b-0003')$q$, 'ok',
  $q$SELECT count(*) FILTER (WHERE price - doc_fee = advertised_price_before_doc AND website_sale_price = price)::text || '/' || count(*)::text
     FROM public.vehicle_listings WHERE tenant_id = 'b0000000-0000-4000-8000-000000000003' AND archived_at IS NULL AND doc_fee = 925$q$,
  '2/2');
SELECT t.check('fee basis: includes fee', 'evidence untouched: verification stamps, parse status and notes, archived and unpriced rows, website observations (stamps|warning|notes|archived fee|unpriced fee|observations)', 'fee_owner',
  $q$SELECT public.admin_doc_fee_change_apply('b0000000-0000-4000-8000-000000000003', true, 925, 1, 'policy-b-0004')$q$, 'ok',
  $q$SELECT concat_ws('|',
       (SELECT count(*) FROM public.vehicle_listings WHERE tenant_id = 'b0000000-0000-4000-8000-000000000003' AND price_last_verified_at::date IN ('2026-10-05', '2026-10-07', '2026-09-05')),
       (SELECT price_parse_status FROM public.vehicle_listings WHERE id = 'c0000000-0000-4000-8000-000000000307'),
       (SELECT left(price_parse_notes, 24) FROM public.vehicle_listings WHERE id = 'c0000000-0000-4000-8000-000000000301'),
       (SELECT doc_fee FROM public.vehicle_listings WHERE id = 'c0000000-0000-4000-8000-000000000306'),
       coalesce((SELECT doc_fee::text FROM public.vehicle_listings WHERE id = 'c0000000-0000-4000-8000-000000000305'), 'null'),
       (SELECT count(*) FROM public.advertised_prices))$q$,
  '3|warning|Advertised price 40420 i|895|null|2');
SELECT t.check('fee basis: includes fee', 'the audit row keeps before and after for each written vehicle (count|traced before>after)', 'fee_owner',
  $q$SELECT public.admin_doc_fee_change_apply('b0000000-0000-4000-8000-000000000003', true, 925, 1, 'policy-b-0005')$q$, 'ok',
  $q$SELECT jsonb_array_length(details->'changes') || '|' || (c->'before'->>'advertised_price_before_doc') || '>' || (c->'after'->>'advertised_price_before_doc')
     FROM public.audit_log, jsonb_array_elements(details->'changes') c
     WHERE action = 'doc_fee_policy_applied' AND c->>'vin_suffix' = '040420'$q$,
  '2|39525>39495.00');
SELECT t.check('fee basis: includes fee', 'reload: a second dry-run at the saved fee finds nothing to change (eligible|unchanged|blocked)', 'fee_owner',
  $q$SELECT public.admin_doc_fee_change_apply('b0000000-0000-4000-8000-000000000003', true, 925, 1, 'policy-b-0006');;
     CREATE TEMP TABLE r ON COMMIT DROP AS SELECT public.admin_doc_fee_change_preview('b0000000-0000-4000-8000-000000000003', true, 925) AS j$q$, 'ok',
  $q$SELECT concat_ws('|', j->>'eligible', j->>'unchanged', j->>'blocked') FROM r$q$,
  '0|2|false');
SELECT t.check('fee basis: includes fee', 'changing back to $895 restores the original split exactly', 'fee_owner',
  $q$SELECT public.admin_doc_fee_change_apply('b0000000-0000-4000-8000-000000000003', true, 925, 1, 'policy-b-0007');;
     SELECT public.admin_doc_fee_change_apply('b0000000-0000-4000-8000-000000000003', true, 895, 2, 'policy-b-0008')$q$, 'ok',
  $q$SELECT t.vrow('c0000000-0000-4000-8000-000000000301')$q$,
  '40420.00|39525.00|895.00|40420');
SELECT t.check('fee basis: includes fee', 'archived stock moves only when explicitly included', 'fee_owner',
  $q$SELECT public.admin_doc_fee_change_apply('b0000000-0000-4000-8000-000000000003', true, 925, 1, 'policy-b-0009', true)$q$, 'ok',
  $q$SELECT t.vrow('c0000000-0000-4000-8000-000000000306')$q$,
  '18000.00|17075.00|925.00|18000');

