-- ── A missing, ambiguous or contradicted basis blocks the change ─────────
DO $$
DECLARE c record;
BEGIN
  FOR c IN SELECT * FROM (VALUES
    ('no setting (display mode alone does not decide)', $s$settings - 'advertised_includes_doc_fee'$s$, 'unconfigured'),
    ('contradicting settings', $s$settings || '{"advertised_excludes_doc_fee": true}'$s$, 'conflict'),
    ('an unreadable setting', $s$settings || '{"advertised_includes_doc_fee": "yes"}'$s$, 'unconfigured')
  ) AS v(label, expr, basis)
  LOOP
    PERFORM t.check('fee basis: authority', c.label || ': apply blocked, nothing written (status|basis|fee setting|version|rows same|blocked audit|ledger)', 'fee_owner',
      format($q$RESET ROLE;;
         UPDATE public.dealer_profiles SET settings = %s WHERE tenant_id = 'b0000000-0000-4000-8000-000000000003';;
         SELECT t.become('fee_owner');;
         CREATE TEMP TABLE r ON COMMIT DROP AS SELECT public.admin_doc_fee_change_apply('b0000000-0000-4000-8000-000000000003', true, 925, t.ver('b0000000-0000-4000-8000-000000000003'), 'policy-b-0020') AS j$q$, c.expr),
      'ok',
      $q$SELECT concat_ws('|', (SELECT j->>'status' FROM r), (SELECT j->>'basis' FROM r),
           (SELECT settings->>'doc_fee_amount' FROM public.dealer_profiles WHERE tenant_id = 'b0000000-0000-4000-8000-000000000003'),
           t.ver('b0000000-0000-4000-8000-000000000003'),
           t.tenant_hash('b0000000-0000-4000-8000-000000000003') = (SELECT h FROM t.hash WHERE tenant_id = 'b0000000-0000-4000-8000-000000000003'),
           (SELECT count(*) FROM public.audit_log WHERE action = 'doc_fee_policy_blocked'),
           (SELECT count(*) FROM public.admin_policy_applications))$q$,
      'blocked|' || c.basis || '|895|2|t|1|0');
  END LOOP;
END $$;
SELECT t.check('fee basis: authority', 'a website observation showing the total minus the fee blocks a fee-inclusive change (blocked|evidence|reason)', 'fee_owner',
  $q$RESET ROLE;;
     INSERT INTO public.advertised_prices (tenant_id, vin, advertised_price, source_channel, captured_at) VALUES ('b0000000-0000-4000-8000-000000000003', 'EXAMPLEVIN0040420', 39525, 'website', '2026-10-20 12:00+00');;
     SELECT t.become('fee_owner');;
     CREATE TEMP TABLE r ON COMMIT DROP AS SELECT public.admin_doc_fee_change_preview('b0000000-0000-4000-8000-000000000003', true, 925) AS j$q$, 'ok',
  $q$SELECT concat_ws('|', j->>'blocked', j->>'evidence_conflicts', j->'block_reasons'->>0) FROM r$q$,
  'true|1|1 vehicle(s) have a website observation that contradicts the configured fee basis.');

-- ── Dealership-level block while conflicts exist ─────────────────────────
SELECT t.expect('fee basis: dealership block', 'dry-run on the conflicted dealership (blocked|eligible|split|invalid|sale price differs|evidence|reasons)', 'conflict_owner',
  $q$SELECT concat_ws('|', r->>'blocked', r->>'eligible', r->>'split_mismatches', r->>'invalid', r->>'source_mismatches', r->>'evidence_conflicts', jsonb_array_length(r->'block_reasons'))
     FROM public.admin_doc_fee_change_preview('b0000000-0000-4000-8000-000000000004', true, 925) r$q$,
  'true|2|1|1|1|1|4');
SELECT t.check('fee basis: dealership block', 'apply refuses the whole change: no fee setting, no vehicle, no ledger; the refusal is audited (status|fee setting|version|rows same|ledger|blocked audit)', 'conflict_owner',
  $q$CREATE TEMP TABLE r ON COMMIT DROP AS SELECT public.admin_doc_fee_change_apply('b0000000-0000-4000-8000-000000000004', true, 925, 1, 'policy-b-0030') AS j$q$, 'ok',
  $q$SELECT concat_ws('|', (SELECT j->>'status' FROM r),
       (SELECT settings->>'doc_fee_amount' FROM public.dealer_profiles WHERE tenant_id = 'b0000000-0000-4000-8000-000000000004'),
       t.ver('b0000000-0000-4000-8000-000000000004'),
       t.tenant_hash('b0000000-0000-4000-8000-000000000004') = (SELECT h FROM t.hash WHERE tenant_id = 'b0000000-0000-4000-8000-000000000004'),
       (SELECT count(*) FROM public.admin_policy_applications),
       (SELECT count(*) FROM public.audit_log WHERE action = 'doc_fee_policy_blocked' AND jsonb_array_length(details->'review'->'block_reasons') = 4))$q$,
  'blocked|895|1|t|0|1');
SELECT t.check('fee basis: dealership block', 'a conflict on one archived vehicle blocks only a change that includes archived stock (active only|with archived)', 'fee_owner',
  $q$RESET ROLE;;
     INSERT INTO public.vehicle_listings (id, store_id, vin, slug, condition, status, tenant_id, created_by, price, advertised_price_before_doc, doc_fee, website_sale_price, archived_at)
     VALUES ('c0000000-0000-4000-8000-000000000309', 'store-3', 'EXAMPLEVIN0011111', 'third-9', 'used', 'archived', 'b0000000-0000-4000-8000-000000000003', 'a0000000-0000-4000-8000-000000000018', 11000, 11000, 895, 11895, now());;
     SELECT t.become('fee_owner');;
     CREATE TEMP TABLE r ON COMMIT DROP AS SELECT public.admin_doc_fee_change_preview('b0000000-0000-4000-8000-000000000003', true, 925) AS a, public.admin_doc_fee_change_preview('b0000000-0000-4000-8000-000000000003', true, 925, true) AS b$q$, 'ok',
  $q$SELECT (a->>'blocked') || '|' || (b->>'blocked') FROM r$q$,
  'false|true');

-- ── Fee-exclusive: the same vehicle priced before the fee ────────────────
SELECT t.check('fee basis: before fee', 'traced vehicle on a before-fee dealership: before-fee 39,525 kept, total 40,420 -> 40,450', 'owner',
  $q$RESET ROLE;;
     INSERT INTO public.vehicle_listings (id, store_id, vin, slug, condition, status, tenant_id, created_by, price, advertised_price_before_doc, doc_fee, website_sale_price, price_parse_status)
     VALUES ('c0000000-0000-4000-8000-000000000199', 'store-1', 'EXAMPLEVIN0039525', 'example-trace', 'used', 'published', 'b0000000-0000-4000-8000-000000000001', 'a0000000-0000-4000-8000-000000000001', 39525, 39525, 895, 40420, 'ok');;
     UPDATE public.dealer_profiles SET settings = settings || '{"advertised_includes_doc_fee": false}' WHERE tenant_id = 'b0000000-0000-4000-8000-000000000001';;
     SELECT t.become('owner');;
     SELECT public.admin_doc_fee_change_apply('b0000000-0000-4000-8000-000000000001', true, 925, t.ver('b0000000-0000-4000-8000-000000000001'), 'policy-b-0101')$q$, 'ok',
  $q$SELECT t.vrow('c0000000-0000-4000-8000-000000000199')$q$,
  '39525.00|39525|925.00|40450.00');
SELECT t.check('fee basis: before fee', 'an inventory price that differs from the before-fee price blocks a fee-exclusive change', 'owner',
  $q$RESET ROLE;;
     UPDATE public.dealer_profiles SET settings = settings || '{"advertised_includes_doc_fee": false}' WHERE tenant_id = 'b0000000-0000-4000-8000-000000000001';;
