  $q$SELECT settings->>'doc_fee_amount' FROM public.dealer_profiles WHERE tenant_id = 'b0000000-0000-4000-8000-000000000003'$q$, '895');
SELECT t.check('fee basis: settings', 'disabling the fee through the settings save is refused too', 'fee_owner',
  $q$SELECT public.merge_dealer_settings('b0000000-0000-4000-8000-000000000003', '{"doc_fee_enabled": false}')$q$, 'error 55000');
SELECT t.check('fee basis: settings', 'resending the saved fee (a whole-settings save) is not a change and passes', 'fee_owner',
  $q$SELECT public.merge_dealer_settings('b0000000-0000-4000-8000-000000000003', '{"doc_fee_amount": "895", "doc_fee_enabled": true, "dealer_name": "Third Example Motors"}')$q$, 'ok');
SELECT t.check('fee basis: settings', 'a dealership without priced vehicles may set its fee directly', 'other_tenant_owner',
  $q$SELECT public.merge_dealer_settings('b0000000-0000-4000-8000-000000000002', '{"doc_fee_amount": 500}')$q$, 'ok',
  $q$SELECT settings->>'doc_fee_amount' FROM public.dealer_profiles WHERE tenant_id = 'b0000000-0000-4000-8000-000000000002'$q$, '500');
SELECT t.check('fee basis: settings', 'the fee basis is a pricing key: a manager can no longer change it', 'fee_manager',
