SELECT t.check('fee basis: settings', 'an owner can set it, and the change is audited as a pricing change', 'fee_owner',
  $q$SELECT public.merge_dealer_settings('b0000000-0000-4000-8000-000000000003', '{"advertised_includes_doc_fee": true}')$q$, 'ok',
  $q$SELECT count(*)::text FROM public.audit_log WHERE action = 'pricing_policy_changed' AND details->'keys' ? 'advertised_includes_doc_fee'$q$, '1');

-- ── The legacy recalculation is retired ──────────────────────────────────
DO $$
DECLARE p text;
BEGIN
  FOREACH p IN ARRAY ARRAY['owner', 'general_manager', 'platform_admin', 'pending_manager', 'salesperson'] LOOP
    PERFORM t.check('fee basis: legacy recalc', 'recalc_tenant_doc_fee refuses every caller and writes nothing', p,
      $q$SELECT public.recalc_tenant_doc_fee('b0000000-0000-4000-8000-000000000001')$q$, 'error 0A000',
      $q$SELECT count(*)::text FROM public.vehicle_listings WHERE price_last_verified_at > now() - interval '1 minute'$q$, '0');
  END LOOP;
END $$;

-- ── Repeats and stale reviews ─────────────────────────────────────────────
SELECT t.check('fee basis: repeats', 'the same review key twice writes once (second status|fee|ledger|applied audits)', 'fee_owner',
  $q$SELECT public.admin_doc_fee_change_apply('b0000000-0000-4000-8000-000000000003', true, 925, 1, 'policy-b-0201');;
     CREATE TEMP TABLE r ON COMMIT DROP AS SELECT public.admin_doc_fee_change_apply('b0000000-0000-4000-8000-000000000003', true, 950, 1, 'policy-b-0201') AS j$q$, 'ok',
  $q$SELECT concat_ws('|', (SELECT j->>'status' FROM r), (SELECT doc_fee FROM public.vehicle_listings WHERE id = 'c0000000-0000-4000-8000-000000000301'),
       (SELECT count(*) FROM public.admin_policy_applications), (SELECT count(*) FROM public.audit_log WHERE action = 'doc_fee_policy_applied'))$q$,
  'duplicate|925.00|1|1');
SELECT t.check('fee basis: repeats', 'a second review against the old version is a conflict and writes nothing more', 'fee_owner',
  $q$SELECT public.admin_doc_fee_change_apply('b0000000-0000-4000-8000-000000000003', true, 925, 1, 'policy-b-0202');;
     CREATE TEMP TABLE r ON COMMIT DROP AS SELECT public.admin_doc_fee_change_apply('b0000000-0000-4000-8000-000000000003', true, 950, 1, 'policy-b-0203') AS j$q$, 'ok',
  $q$SELECT concat_ws('|', (SELECT j->>'status' FROM r), (SELECT doc_fee FROM public.vehicle_listings WHERE id = 'c0000000-0000-4000-8000-000000000301'))$q$,
  'conflict|925.00');

